('she is reading a good book', 5, 'book', 'noun'),
('can I have some more coffee', 0, 'can', 'verb'),
('can I have some more coffee', 1, 'I', 'pronoun'),
('can I have some more coffee', 2, 'have', 'verb'),
('can I have some more coffee', 3, 'some', 'determiner'),
('can I have some more coffee', 4, 'more', 'determiner'),
('can I have some more coffee', 5, 'coffee', 'noun'),
('the weather is very nice today', 0, 'the', 'article'),
('the weather is very nice today', 1, 'weather', 'noun'),
('the weather is very nice today', 2, 'is', 'verb'),
('the weather is very nice today', 3, 'very', 'adverb'),
('the weather is very nice today', 4, 'nice', 'adjective'),
('the weather is very nice today', 5, 'today', 'adverb'),
('he always walks to work early', 0, 'he', 'pronoun'),
('he always walks to work early', 1, 'always', 'adverb'),
('he always walks to work early', 2, 'walks', 'verb'),
('he always walks to work early', 3, 'to', 'preposition'),
('he always walks to work early', 4, 'work', 'noun'),
('he always walks to work early', 5, 'early', 'adverb'),
('make English part of your day', 0, 'make', 'verb'),
('make English part of your day', 1, 'English', 'noun'),
('make English part of your day', 2, 'part', 'noun'),
('make English part of your day', 3, 'of', 'preposition'),
('make English part of your day', 4, 'your', 'determiner'),
('make English part of your day', 5, 'day', 'noun')
) as v(phrase, word_index, word, pos)
join public.phrases p on p.text = v.phrase
join public.words   w on w.text = v.word and w.pos = v.pos
on conflict (phrase_id, word_index) do update set word_id = excluded.word_id;

commit;
